?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Saved Complete Looks</title><style>body{font-family:Arial;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{background:#1A1108;color:#C9A84C;padding:18px 28px}.nav a{color:#E8CC82;margin-left:18px;text-decoration:none}.main{max-width:950px;margin:auto;padding:30px}.hero,.card{background:#fff;border:1px solid #E8E0D0;padding:22px;margin-bottom:18px}.hero{background:#21170B;color:#fff}.look{border-top:1px solid #eee;padding:16px 0}.tag{display:inline-block;background:#F6F0E5;padding:6px;margin:3px;font-size:11px}.btn{padding:8px 12px;border:0;background:#1A1108;color:#C9A84C}.delete{background:#7F1D1D;color:#fff}.small{font-size:12px;color:#777;line-height:1.5}.item{margin:10px 0;padding:12px;background:#FAF6EE}</style></head><body><div class="nav"><b>O2O Tradition</b><a href="home.php">Home</a><a href="complete_look.php">Create Look</a></div><main class="main"><section class="hero"><h1>♡ Saved Complete Looks</h1><p>Revisit looks you created with the AI stylist. Catalogue availability can change.</p></section><?php if(!$looks):?><section class="card">No saved looks yet. <a href="complete_look.php">Create your first complete look.</a></section><?php else:foreach($looks as $look):$data=json_decode($look['look_data'],true)?:[];?><section class="card look"><h2><?=htmlspecialchars($look['occasion'])?> · <?=htmlspecialchars(ucfirst($look['mode']))?></h2><div class="small"><?=date('d M Y, h:i A',strtotime($look['created_at']))?><?php if((float)$look['budget']>0):?> · Budget ₹<?=number_format((float)$look['budget'],0)?><?php endif;?></div><?php if($look['intro']):?><p><?=htmlspecialchars($look['intro'])?></p><?php endif;?><?php foreach($data as $x):$p=$x['product']??[];?><div class="item"><b><?=htmlspecialchars($p['name']??'Saved outfit')?></b><?php if(isset($p['id'])):?><br><a href="item.php?id=<?=(int)$p['id']?>">View current item</a><?php endif;?><p class="small"><?=htmlspecialchars($x['why']??'')?></p><?php if(!empty($x['jewellery'])):?><span class="tag">💎 <?=htmlspecialchars($x['jewellery'])?></span><?php endif;?><?php if(!empty($x['footwear'])):?><span class="tag">👞 <?=htmlspecialchars($x['footwear'])?></span><?php endif;?><?php if(!empty($x['bag_or_accessory'])):?><span class="tag">👜 <?=htmlspecialchars($x['bag_or_accessory'])?></span><?php endif;?></div><?php endforeach;?><form method="POST"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$look['id']?>"><button class="btn delete">Delete Saved Look</button></form></section><?php endforeach;endif;?></main></body></html>